DERIVATIONS = {}


def lesson(number, references, *items):
    DERIVATIONS[number] = dict(review_chapters=references, items=list(items))


def derive(title, concept, assumptions, steps, result, check):
    return dict(title=title, concept=concept, assumptions=assumptions,
                steps=steps, result=result, check=check)


lesson(1, [1],
    derive('Unit conversion and dimensions',
           'A quantity stays the same when we multiply it by a conversion factor equal to one. Dimensions track the kind of quantity independently of its unit.',
           'Use consistent base dimensions: length L, mass M, and time T. Unit conversions below are exact.',
           ['Start with 1 km/h and multiply by (1000 m / 1 km)(1 h / 3600 s). The km and h cancel.',
            'The remaining factor is 1000/3600 m/s = 1/3.6 m/s.',
            'Velocity is displacement per time, so [v] = L/T. Acceleration is velocity change per time, so [a] = L/T².',
            'From the physical law F = ma, [F] = M(L/T²). Likewise, density defined by ρ = m/V has dimension M/L³.'],
           '1 km/h = (1/3.6) m/s; [v] = LT⁻¹; [a] = LT⁻²; [F] = MLT⁻²',
           'Both v₀t and at² have dimension L. Dimensional agreement cannot determine the factor ½ in the displacement equation; that needs the motion model.'))

lesson(2, [2],
    derive('Constant acceleration from slopes and graph areas',
           'Acceleration is the slope of a velocity–time graph; displacement is its signed area. A constant slope produces a straight line.',
           'One-dimensional motion with constant acceleration a over elapsed time t; x₀ and v₀ are initial values.',
           ['The definition a = (v − v₀)/t rearranges to v = v₀ + at.',
            'The area under the straight velocity graph is a rectangle v₀t plus a signed triangle ½(v − v₀)t.',
            'Substitute v − v₀ = at into that area to obtain Δx = v₀t + ½at².',
            'Equivalently, Δx = ½(v + v₀)t. Multiply 2aΔx = a(v + v₀)t and use at = v − v₀ to get 2aΔx = v² − v₀².'],
           'v = v₀ + at; Δx = v₀t + ½at²; v² = v₀² + 2aΔx',
           'At a = 0, displacement reduces to v₀t. These graph areas remain signed when velocity is negative; total distance instead uses the area under |v|.'),
    derive('The calculus connection for changing acceleration',
           'A derivative is an instantaneous rate, and an integral adds small changes. The graph interpretation extends to curved graphs.',
           'Motion is sufficiently smooth; a(t) may vary. Definite integrals run from the initial time 0 to the current time t.',
           ['Define v = dx/dt and a = dv/dt. Thus dv = a(t) dt.',
            'Adding velocity changes gives v(t) = v₀ + ∫₀ᵗ a(s) ds, where s is a dummy time variable.',
            'Adding displacements gives x(t) = x₀ + ∫₀ᵗ v(s) ds. For constant a, integrating v₀ + as produces v₀t + ½at².'],
           'v(t) = v₀ + ∫₀ᵗ a(s) ds; x(t) = x₀ + ∫₀ᵗ v(s) ds',
           'The units of each integral are the vertical-axis units times seconds: acceleration area gives m/s, and velocity area gives m.'))

lesson(3, [3, 4],
    derive('Components, relative velocity, and projectile range',
           'Perpendicular vector components can be handled independently, but describe the same elapsed time.',
           'Projectile: negligible drag, constant downward g, horizontal x and upward y. Range and flight time shortcuts require equal launch and landing height and 0 < θ < 90°.',
           ['Right-triangle projections give v₀ₓ = v₀ cos θ and v₀ᵧ = v₀ sin θ. Apply the one-dimensional motion equations with aₓ = 0 and aᵧ = −g.',
            'This gives Δx = v₀ cos(θ)t and Δy = v₀ sin(θ)t − ½gt².',
            'At the landing height, 0 = T[v₀ sin θ − ½gT]. Excluding the launch solution T = 0 gives T = 2v₀ sin θ/g.',
            'Then R = v₀ cos θ · T = 2v₀² sin θ cos θ/g. Use 2 sin θ cos θ = sin(2θ).',
            'For relative motion, positions obey r(A/C) = r(A/B) + r(B/C). Taking their time rates gives the corresponding vector velocity sum.'],
           'R = v₀² sin(2θ)/g; T = 2v₀ sin θ/g; v(A/C) = v(A/B) + v(B/C)',
           'At 45°, sin(2θ) is largest. A cliff launch changes the vertical landing condition, so the equal-height range formula no longer applies.'))

lesson(4, [5, 6],
    derive('Newton’s law, weight, normal force, and friction',
           'Newton’s second law is a starting physical law. Weight and contact forces enter its vector sum; friction coefficients summarize measured surface behaviour.',
           'Inertial frame, constant mass, nonrelativistic speeds. The friction model approximates dry sliding contact.',
           ['The momentum form ΣF = dp/dt becomes ΣF = ma when p = mv and mass is constant. This reformulates the law rather than proving it from algebra.',
            'A freely falling object has acceleration g downward. Its gravitational force therefore has magnitude W = mg.',
            'For an object on an incline with no other perpendicular force and no perpendicular acceleration, N − mg cos θ = 0, so N = mg cos θ.',
            'Static friction supplies the force needed to prevent slip, up to μₛN. If a block rests on the incline, fₛ = mg sin θ and mg sin θ ≤ μₛmg cos θ.',
            'At impending slip tan θ = μₛ. Once sliding downhill, the model fₖ = μₖN gives a = g(sin θ − μₖ cos θ).'],
           'ΣF = ma; W = mg; fₛ ≤ μₛN; fₖ = μₖN; tan θ_threshold = μₛ',
           'On a horizontal surface with no vertical pull, N = mg. In an accelerating lift or with an angled pull, derive N again from the perpendicular force equation.'))

lesson(5, [4, 6, 13],
    derive('Why circular acceleration is v²/r',
           'In uniform circular motion, the speed is constant while the velocity direction rotates through the same angle as the radius.',
           'Constant speed on a circle of radius r. Use the limiting geometry of a very short time interval Δt.',
           ['Two nearby velocity vectors both have length v. Their difference has magnitude |Δv| = 2v sin(Δθ/2).',
            'For a small angle in radians, 2 sin(Δθ/2) approaches Δθ. The arc travelled is Δs = rΔθ = vΔt.',
            'Thus |Δv|/Δt approaches vΔθ/Δt = v(v/r) = v²/r. The limiting change points toward the centre.',
            'One full lap covers 2πr in period T, so v = 2πr/T. Newton’s law then requires an inward net force mv²/r.'],
           'aᵣ = v²/r = ω²r; ΣFᵣ = mv²/r; v = 2πr/T',
           'Doubling speed quadruples the required radial force. The force diagram must identify which actual interactions supply that resultant.'),
    derive('Circular orbits, Kepler’s scaling, and gravitational energy',
           'Gravity supplies the inward force for a circular orbit. Its inverse-square form also determines how potential energy changes with separation.',
           'Newtonian gravity, spherical central body of mass M, satellite mass m ≪ M, radius r measured from the centre; U = 0 at infinity.',
           ['Start with the gravitational law F = GMm/r². Setting F = mg gives g(r) = GM/r².',
            'For a circular orbit, GMm/r² = mv²/r. Cancel m and one factor of r to obtain v² = GM/r.',
            'Use T = 2πr/v and square to find T² = 4π²r³/(GM). For elliptical orbits the same period relation uses semimajor axis instead of circular radius.',
            'The outward radial force component is Fᵣ = −GMm/r². Since dU = −Fᵣ dr, integrating from infinity to r gives U(r) = −GMm/r.',
            'Near a surface of radius R, ΔU = GMm(1/R − 1/(R+h)) ≈ (GM/R²)mh = mgh when h ≪ R.'],
           'v_orbit = √(GM/r); T² = 4π²r³/(GM); U = −GMm/r',
           'A more distant circular orbit has lower speed and a longer period. The familiar mgh is a local approximation to the inverse-square potential.'))

lesson(6, [7, 8],
    derive('Work–energy theorem and kinetic energy',
           'Work accumulates the component of force along displacement. Applying Newton’s law to this accumulated work produces the speed-squared energy expression.',
           'A particle of constant mass at nonrelativistic speed; W_net uses all forces acting on it.',
           ['For a constant force, project along displacement: W = (F cos θ)d. For a variable force, add small contributions: W = ∫F · dr.',
            'In one dimension, a = dv/dt = v dv/dx. Therefore F dx = ma dx = mv dv.',
            'Integrate between the initial and final speeds: W_net = ∫ mv dv = ½mv_f² − ½mv_i². The vector derivation gives the same result.',
            'Define K = ½mv², so W_net = ΔK. Dividing a small work increment by dt gives P = F · v = Fv cos θ; over a finite interval P_avg = W/Δt.'],
           'K = ½mv²; W_net = ΔK; P = Fv cos θ',
           'A force perpendicular to velocity changes direction without instantaneous work. Work and kinetic energy both have units N·m = J.'),
    derive('Potential energy and mechanical energy accounting',
           'For a conservative force, define potential energy so that its decrease equals the work done by that force.',
           'Uniform near-Earth gravity and an ideal Hooke-law spring within its elastic range; choose convenient zero levels.',
           ['Use ΔU = −W_conservative. With upward y, gravity has Fᵧ = −mg, so ΔU_g = −∫(−mg) dy = mgΔy.',
            'A spring exerts F = −kx. Thus U_s(x) − U_s(0) = −∫₀ˣ(−ks) ds = ½kx².',
            'Split net work into conservative and nonconservative parts: ΔK = −ΔU + W_nc.',
            'Rearrange to Kᵢ + Uᵢ + W_nc = K_f + U_f. If W_nc = 0, total mechanical energy stays constant.'],
           'U_g = mgy; U_s = ½kx²; Δ(K + U) = W_nc',
           'For sliding friction, W_nc is typically negative and mechanical energy decreases while thermal energy increases. Changing the zero of U cannot change a predicted speed.'))

lesson(7, [9],
    derive('Impulse, momentum conservation, and centre of mass',
           'Internal forces transfer momentum within a system; only external impulse changes its total momentum.',
           'Constant particle masses in an inertial frame. Internal Newton-third-law force pairs cancel in the system sum.',
           ['Define each momentum by pᵢ = mᵢvᵢ. Newton’s law gives F_net = dp/dt, so integrating gives J = ∫F_net dt = Δp = F_avg Δt.',
            'Sum over particles. Each internal force has an equal and opposite partner, leaving dP/dt = ΣF_external.',
            'If the external impulse during a collision is negligible, P_f − P_i = 0 even when the collision is inelastic.',
            'Define x_CM = Σmᵢxᵢ/M, with M = Σmᵢ. Differentiate to obtain Mv_CM = Σmᵢvᵢ = P, and differentiate again to obtain Ma_CM = ΣF_external.'],
           'J = Δp; P_f = P_i if J_external = 0; x_CM = Σmᵢxᵢ/M',
           'Two sticking carts share v_f = (m₁v₁ + m₂v₂)/(m₁+m₂). Their kinetic energy usually changes; the conserved quantity is the system momentum.'))

lesson(8, [10, 11],
    derive('Angular motion, torque, and rotational inertia',
           'A rigid body shares one angular motion, but mass farther from the axis travels faster and contributes more to rotational inertia.',
           'Rigid body rotating about a fixed axis with constant I. Angles use radians. The scalar angular momentum formula refers to that axis component or to a principal axis.',
           ['Arc length is s = rθ. Taking time rates gives v_t = rω and a_t = rα. For rolling without slip on stationary ground, the contact point has zero velocity, giving v_CM = Rω.',
            'For each mass element, tangential force is F_t = m rα. Its axial torque is rF_t = mr²α; summing gives Στ = (Σmr²)α = Iα.',
            'Sum particle kinetic energies: K_rot = Σ½m(rω)² = ½Iω².',
            'Sum angular momentum components: L_axis = Σr(mv_t) = Σmr²ω = Iω. With zero external axial torque, this component is conserved.',
            'For constant α, the straight-line equations carry over: ω = ω₀ + αt and Δθ = ω₀t + ½αt².'],
           'I = Σmᵢrᵢ²; Στ = Iα; K_rot = ½Iω²; L_axis = Iω',
           'Moving the same mass twice as far from the axis multiplies its contribution to I by four. For a general force, the lever arm gives τ = rF sin θ.'),
    derive('Rolling downhill: translation plus rotation',
           'A rolling object divides its gravitational energy between motion of its centre and rotation about its centre.',
           'Rigid body rolling without slipping from rest through height h; fixed incline, no dissipative losses, I = κmR² about its centre.',
           ['Conservation gives mgh = ½mv_CM² + ½Iω².',
            'Insert ω = v_CM/R and I = κmR², so mgh = ½m(1 + κ)v_CM².',
            'Cancel mass and solve. For a uniform solid disk κ = ½; for a thin hoop κ = 1.'],
           'v_CM = √[2gh/(1 + κ)]',
           'A disk reaches the bottom faster than a hoop from the same height because it needs less rotational energy at a given centre speed. Static friction must be sufficient to enforce the no-slip condition.'))

lesson(9, [12],
    derive('Equilibrium conditions and elastic extension',
           'An object that remains at rest has neither translational nor angular acceleration. A linear elastic material has stress proportional to strain.',
           'Planar rigid-body equilibrium; a uniform rod or wire under small axial elastic deformation.',
           ['Set a_CM = 0 in ΣF = Ma_CM. Set α = 0 in the fixed-axis torque equation. In a plane this gives ΣFₓ = 0, ΣFᵧ = 0, and Στ = 0.',
            'Define stress = F/A and strain = ΔL/L₀. Young’s modulus is their ratio in the linear elastic regime: Y = (F/A)/(ΔL/L₀).',
            'Rearrange to ΔL = FL₀/(AY). This has the spring form F = k_eff ΔL with k_eff = AY/L₀.',
            'Similarly, linear bulk response uses bulk modulus B = −ΔP/(ΔV/V), with the minus sign accounting for compression when pressure rises.'],
           'ΣFₓ = ΣFᵧ = Στ = 0; ΔL = FL₀/(AY); B = −VΔP/ΔV',
           'Doubling wire length doubles its extension under the same force; doubling cross-sectional area halves it. Force balance alone cannot rule out rotation.'))

lesson(10, [14],
    derive('Hydrostatic pressure and buoyancy',
           'A fluid at rest must balance the weight of each small fluid element. Pressure differences then produce the upward buoyant force.',
           'Uniform density ρ, constant g, static fluid, depth h measured downward from pressure P₀.',
           ['Take a vertical fluid column with area A and height h. Its weight is ρAhg.',
            'Vertical balance gives P_bottom A − P₀A − ρAhg = 0. Dividing by A gives P = P₀ + ρgh.',
            'For a submerged rectangular volume, the bottom–top pressure difference is ρg(height). Multiplying by its area gives F_b = ρgV_displaced; side forces cancel.',
            'The same displaced-fluid argument works for other shapes. For a floating object, ρ_fluid V_sub g = mg, so V_sub/V_object = ρ_object/ρ_fluid.'],
           'P = P₀ + ρgh; F_b = ρ_fluid V_displaced g',
           'A fully submerged rigid object in an incompressible liquid displaces the same volume at different depths, so its buoyant force is unchanged.'),
    derive('Continuity and Bernoulli from conservation',
           'Steady flow conserves mass. Pressure work changes the kinetic and gravitational energy of a parcel.',
           'Steady, incompressible, nonviscous flow along a streamline, with no pump or turbine between the chosen points.',
           ['In time Δt, volume A₁v₁Δt enters a tube segment and A₂v₂Δt leaves. With no accumulation, A₁v₁ = A₂v₂.',
            'Follow a parcel of volume ΔV. Upstream pressure does P₁ΔV work; downstream pressure removes P₂ΔV.',
            'The net work equals ½ρΔV(v₂² − v₁²) + ρgΔV(y₂ − y₁).',
            'Divide by ΔV and regroup each point’s terms to obtain Bernoulli’s equation.'],
           'A₁v₁ = A₂v₂; P + ½ρv² + ρgy = constant along a streamline',
           'All three Bernoulli terms have units J/m³ = Pa. A horizontal constriction raises ideal flow speed and lowers static pressure.'))

lesson(11, [15, 16],
    derive('Spring and pendulum periods from restoring forces',
           'Simple harmonic motion occurs when acceleration is proportional to displacement and points back toward equilibrium.',
           'Ideal undamped spring with mass m; simple pendulum with length ℓ and small angle θ in radians.',
           ['Hooke’s empirical law F = −kx and Newton’s law give d²x/dt² = −(k/m)x.',
            'For x = A cos(ωt + φ), the second derivative is −ω²x. Matching coefficients yields ω² = k/m; since ω = 2π/T, T = 2π√(m/k).',
            'A pendulum’s tangential acceleration is ℓ d²θ/dt². Its tangential force is −mg sin θ ≈ −mgθ, so d²θ/dt² = −(g/ℓ)θ.',
            'The same comparison gives T ≈ 2π√(ℓ/g). At a spring turning point, E = ½kA²; at equilibrium E = ½mv_max², hence v_max = A√(k/m).'],
           'T_spring = 2π√(m/k); T_pendulum ≈ 2π√(ℓ/g); v_max = A√(k/m)',
           'The ideal period does not depend on spring amplitude. A large-angle pendulum violates sin θ ≈ θ, and its period increases with amplitude.'),
    derive('Wave speed and standing-wave frequencies',
           'A fixed wave phase moves one wavelength in one period. Standing-wave modes must also satisfy the boundaries.',
           'Linear sinusoidal waves; a uniform string of length L fixed at both ends. Tension F_T and linear mass density μ are constant.',
           ['Write y(x,t) = A sin(kx − ωt), with k = 2π/λ and ω = 2πf. Holding phase fixed gives k dx/dt − ω = 0, so v = ω/k = fλ.',
            'For a small string element dx, the difference between endpoint transverse tension components is F_T(∂²y/∂x²)dx.',
            'Newton’s law with element mass μdx gives ∂²y/∂t² = (F_T/μ)∂²y/∂x². Substitution of the sinusoid gives v² = F_T/μ.',
            'Fixed ends require nodes at both boundaries, so L = nλ/2 with n = 1, 2, … . Substitute λ_n = 2L/n into f = v/λ.'],
           'v = fλ = √(F_T/μ); f_n = nv/(2L); f = 1/T',
           'Higher string tension raises all mode frequencies. The medium particles oscillate transversely; their speed is different from the phase speed v.'))

lesson(12, [17],
    derive('Sound level, spreading, and beats',
           'Intensity is energy flow per area. Decibels compare intensities logarithmically, while beats arise from superposing nearby frequencies.',
           'For inverse-square spreading, an isotropic source in a lossless open medium; for beats, two coherent tones with close frequencies.',
           ['A source of acoustic power P sends that power through a sphere of area 4πr², giving I = P/(4πr²).',
            'Sound level is defined as β = 10 log₁₀(I/I₀), with I₀ = 10⁻¹² W/m². Therefore a tenfold intensity increase adds 10 dB; doubling adds about 3 dB.',
            'Use cos(2πf₁t) + cos(2πf₂t) = 2 cos[π(f₁ − f₂)t] cos[π(f₁ + f₂)t].',
            'The magnitude of the slow envelope has successive loud peaks separated by 1/|f₁ − f₂|, so f_beat = |f₁ − f₂|.'],
           'I = P/(4πr²); β = 10 log₁₀(I/I₀); f_beat = |f₁ − f₂|',
           'Doubling distance quarters intensity and lowers level by about 6 dB under the spreading assumptions. A zero frequency difference gives no beats.'),
    derive('Pipe modes and the Doppler equation',
           'Pipe boundaries fix allowed wavelengths. Relative source and observer motion changes the spacing and arrival rate of sound wavefronts.',
           'Ideal pipe with one closed end; one-dimensional classical sound in a stationary medium. Speeds are relative to the medium; source motion stays subsonic.',
           ['A closed end is a displacement node, and an open end is approximately a displacement antinode. Thus L = nλ/4 for n = 1, 3, 5, …, giving f_n = nv/(4L).',
            'A source emits crests every T_s = 1/f_s. Moving toward the observer by v_sT_s shortens their spacing to λ_front = (v − v_s)T_s.',
            'An observer moving toward the source meets those crests at relative speed v + v_o. Divide the encounter speed by λ_front.',
            'This yields f_observed = f_s(v + v_o)/(v − v_s), with v_o positive toward the source and v_s positive toward the observer.'],
           'f_n = nv/(4L), n odd; f_observed = f_s(v + v_o)/(v − v_s)',
           'For stationary source and observer, the observed frequency equals f_s. End corrections and real pipe geometry shift the ideal mode frequencies.'))

lesson(13, [18, 19],
    derive('Temperature scales and thermal expansion',
           'Temperature conversion is a scale definition. Expansion coefficients quantify a measured fractional change per degree.',
           'A uniform object over a small temperature interval where the linear expansion coefficient α is approximately constant.',
           ['The Kelvin and Celsius scales have equal increments and offset zero points: T(K) = T(°C) + 273.15.',
            'Define α ≈ (ΔL/L₀)/ΔT. Rearranging gives ΔL = αL₀ΔT.',
            'For an isotropic solid, V = L³. A small fractional change gives ΔV/V ≈ 3ΔL/L, so the volume expansion coefficient is approximately 3α.'],
           'T(K) = T(°C) + 273.15; ΔL = αL₀ΔT; ΔV ≈ 3αV₀ΔT',
           'A temperature difference of 10°C is 10 K. An absolute temperature in an ideal-gas equation must be in kelvins.'),
    derive('Gas pressure, molecular energy, and rms speed',
           'Pressure comes from repeated molecular momentum transfers to container walls. Temperature measures the mean translational kinetic energy of an ideal gas.',
           'Dilute classical ideal gas in thermal equilibrium, isotropic molecular velocities, elastic wall collisions, negligible interaction energy.',
           ['In a cubical box of side L, a molecule with x-speed vₓ reverses momentum by 2mvₓ every 2L/|vₓ|. Its average x-force contribution is mvₓ²/L.',
            'Divide the sum of forces by wall area L²: P = Nm⟨vₓ²⟩/V. Isotropy gives ⟨vₓ²⟩ = ⟨v²⟩/3, so PV = Nm⟨v²⟩/3.',
            'Combine this mechanical result with the ideal-gas equation of state PV = Nk_B T. Then ½m⟨v²⟩ = 3k_B T/2.',
            'By definition v_rms = √⟨v²⟩, hence v_rms = √(3k_B T/m). With N = nN_A and R = N_Ak_B, PV = nRT.'],
           'PV = nRT = Nk_B T; ⟨K_trans⟩ = 3k_B T/2; v_rms = √(3k_B T/m)',
           'At the same temperature, lighter molecules have larger rms speed but the same mean translational kinetic energy. The wall argument alone does not define an absolute temperature scale.'))

lesson(14, [18],
    derive('Heating, phase changes, and calorimetry',
           'Specific heat and latent heat are material properties defined by how much energy a process transfers.',
           'Approximately constant specific heat c or latent heat L over the interval; an isolated calorimeter includes every participating body and container.',
           ['Define c = (1/m)dQ/dT for the specified process. Integrating with constant c gives Q = mc(T_f − T_i).',
            'During a specified equilibrium phase change, transferred energy changes the phase fraction at nearly fixed temperature. Define L = Q_phase/m, giving Q_phase = mL.',
            'Energy conservation for an isolated set of bodies requires ΣQ = 0. Assign positive Q to energy gained and negative Q to energy lost.',
            'For two bodies with no phase change, m₁c₁(T_f − T₁) + m₂c₂(T_f − T₂) = 0. Solve for their shared final temperature.'],
           'Q = mcΔT; Q_phase = mL; ΣQ = 0',
           'Without a phase change or reaction, the final isolated equilibrium temperature lies between the starting temperatures. Include separate warming, phase-change, and cooling terms when needed.'),
    derive('Conduction and net thermal radiation',
           'Heat-flow laws describe measured material response. Geometry and energy balance convert them into useful power formulas.',
           'Steady one-dimensional conduction through a uniform slab; grey-body radiation to large surroundings of uniform temperature, with an appropriate emissivity ε.',
           ['Fourier’s empirical conduction law is P = −kA dT/dx, with the sign indicating flow toward lower temperature.',
            'For constant k, no internal heat generation, and steady flow through thickness ℓ, temperature varies linearly, so the magnitude is P = kA(T_hot − T_cold)/ℓ.',
            'Stefan–Boltzmann emission is P_emit = εσAT⁴. Absorption from the specified surroundings contributes εσAT_surr⁴ under the grey-body model.',
            'Subtract absorbed power from emitted power to find net outward radiative transfer.'],
           'P_conduction = kAΔT/ℓ; P_rad,net = εσA(T⁴ − T_surr⁴)',
           'At T = T_surr, net radiation is zero even though both bodies continue emitting. The fourth powers require absolute temperatures.'))

lesson(15, [18, 19, 20],
    derive('First law and ideal-gas work',
           'Internal energy changes through heat entering a system and work leaving it. Gas expansion does mechanical work against external pressure.',
           'Closed system with work positive when done by the system; quasistatic ideal-gas paths when gas pressure is used in the work integral.',
           ['A piston displacement dx changes volume by dV = A dx. Pressure force PA does work dW = PA dx = P dV.',
            'Energy conservation therefore gives ΔU = Q − W, with W = ∫P dV. At constant pressure this becomes PΔV.',
            'On a reversible isothermal ideal-gas path, P = nRT/V. Integrate to get W = nRT ln(V_f/V_i). Since ideal-gas internal energy depends only on T, ΔU = 0 and Q = W.',
            'For an ideal gas with constant heat capacities on a reversible adiabatic path, Q = 0 and dU = nC_V dT = −P dV.',
            'Insert P = nRT/V and integrate C_V dT/T = −R dV/V. With γ = C_P/C_V and C_P − C_V = R, obtain TV^(γ−1) = constant, or PV^γ = constant.'],
           'ΔU = Q − W; W = ∫P dV; W_isothermal = nRT ln(V_f/V_i); PV^γ = constant (reversible adiabatic)',
           'Expansion work is positive. An irreversible free expansion cannot be evaluated by inserting the gas pressure into a quasistatic work integral.'),
    derive('Heat-engine efficiency, entropy, and the Carnot limit',
           'A cyclic engine cannot turn all absorbed heat into work while also obeying the second law. Entropy accounts for the direction of the heat transfers.',
           'Engine operates between reservoirs at fixed T_H > T_C > 0 K; Q_H and Q_C are positive heat magnitudes.',
           ['Over one cycle, ΔU = 0, so W_out = Q_H − Q_C. Divide by Q_H to get η = 1 − Q_C/Q_H.',
            'Entropy change is defined along a reversible comparison path by dS = δQ_rev/T. For reversible isothermal transfer, ΔS = Q_rev/T.',
            'A reversible cyclic engine has zero total reservoir entropy change: −Q_H/T_H + Q_C/T_C = 0. Hence Q_C/Q_H = T_C/T_H.',
            'Substitute to get η_Carnot = 1 − T_C/T_H. An irreversible engine produces entropy, so Q_C/T_C ≥ Q_H/T_H and η ≤ η_Carnot.',
            'At constant volume, heating an ideal gas with constant C_V gives ΔS = ∫nC_V dT/T = nC_V ln(T_f/T_i). A gas entropy change can be calculated this way even if the actual path is irreversible.'],
           'η = 1 − Q_C/Q_H ≤ 1 − T_C/T_H; ΔS = ∫δQ_rev/T; ΔS_universe ≥ 0',
           'As reservoir temperatures approach equality, maximum efficiency approaches zero. A subsystem may lose entropy while the total entropy still increases.'))

lesson(16, [21, 22, 23],
    derive('Coulomb force, field, and superposition',
           'Electric field describes the force per unit test charge from a source configuration. Coulomb’s inverse-square law is an experimental starting law.',
           'Electrostatic point charges in vacuum; a test charge small enough not to disturb the source distribution.',
           ['Coulomb’s law gives force magnitude F = k_e|Qq|/r². Define E = F/q for a positive test charge, including its direction.',
            'Cancel test-charge magnitude to obtain E = k_e|Q|/r²; the direction is outward for Q > 0 and inward for Q < 0.',
            'For any test charge, the vector force is F = qE. A negative q reverses the direction.',
            'The superposition principle adds vector field contributions: E_total = ΣEᵢ. Resolve components before summing magnitudes.'],
           'E_point = k_e|Q|/r²; F = qE; E_total = ΣEᵢ',
           'At the midpoint of two equal positive charges, the vector fields cancel even though the scalar electric potentials add.'),
    derive('Gauss’s law: spherical, line, and sheet symmetry',
           'Electric flux counts the normal field through a surface. A closed-surface flux is fixed by the enclosed charge; symmetry is what lets us extract E from that flux.',
           'Vacuum electrostatics. Spherical, infinitely long line, and infinite-sheet results require their stated symmetries; θ is between field and area normal.',
           ['For a uniform field on a flat area, Φ_E = EA cos θ. Gauss’s law states ∮E · dA = Q_enclosed/ε₀.',
            'For spherical symmetry, E is radial and constant on a sphere: E(4πr²) = Q_enclosed/ε₀. Outside the source, E = Q/(4πε₀r²).',
            'For a line with charge per length λ_q, use a cylinder of radius r and length ℓ. End flux is zero and side flux is E(2πrℓ), giving E = |λ_q|/(2πε₀r).',
            'For a sheet of surface charge density σ_q, a pillbox has flux EA on each cap, so 2EA = |σ_q|A/ε₀ and E = |σ_q|/(2ε₀).',
            'For a conductor in electrostatic equilibrium the interior field vanishes. A pillbox across its surface then gives E_outside = |σ_q|/ε₀.'],
           '∮E · dA = Q_enclosed/ε₀; E_sphere = k_e|Q|/r²; E_sheet = |σ_q|/(2ε₀)',
           'Zero enclosed charge means zero net flux; it does not by itself imply zero field. An external uniform field can enter one side of a closed surface and leave the other.'))

lesson(17, [24, 25],
    derive('Potential from electric work',
           'Potential difference is the potential-energy change per charge. It is related to the field by accumulated work, not by a vector sum of potential values.',
           'Electrostatic fields; point-charge potential uses zero at infinity. The uniform-field formula uses displacement along the chosen field axis.',
           ['Electric work is W_e = ∫qE · dr. Since ΔU = −W_e, divide by q to obtain ΔV = −∫E · dr and ΔU = qΔV.',
            'Along a uniform field in the +x direction, the integral gives ΔV = −EΔx. Potential falls in the field direction.',
            'For a source Q, the outward radial field is k_eQ/r². Integrate V(r) − V(∞) = −∫∞ʳ k_eQ/s² ds to get V = k_eQ/r.',
            'A charge e through 1 V changes energy by e × 1 J/C, defining 1 eV = 1.602 × 10⁻¹⁹ J.'],
           'ΔU = qΔV; ΔV = −∫E · dr; V_point = k_eQ/r',
           'A positive charge released in an electric field tends toward lower potential. For a negative charge, lower potential energy instead means higher potential.'),
    derive('Capacitance, stored energy, and capacitor combinations',
           'Capacitance connects stored separated charge to voltage. Charging progressively costs more work because the existing charge raises the voltage.',
           'Ideal parallel plates, separation d much smaller than plate dimensions, linear dielectric of permittivity ε, negligible edge fields.',
           ['Oppositely charged sheets produce E = Q/(εA) between the plates. Voltage magnitude is V = Ed = Qd/(εA).',
            'Using the definition C = Q/V gives C = εA/d.',
            'During charging, a small charge dq moves through V(q) = q/C, so dU = (q/C)dq. Integrate from 0 to Q: U = Q²/(2C) = ½CV².',
            'Parallel capacitors share V and add charge: Q_total = ΣCᵢV, so C_parallel = ΣCᵢ.',
            'Series capacitors with initially neutral isolated intermediate conductors carry equal charge magnitudes. Voltages add: V_total = ΣQ/Cᵢ, so 1/C_series = Σ1/Cᵢ.'],
           'C = εA/d; U_C = Q²/(2C) = ½CV²; C_parallel = ΣCᵢ; 1/C_series = Σ1/Cᵢ',
           'For fixed voltage, inserting a dielectric increases stored charge and energy; for an isolated fixed-charge capacitor it lowers voltage and energy. State which constraint applies.'))

lesson(18, [26, 31],
    derive('Current, resistance, and electrical power',
           'Current measures charge flow, while resistance connects the field driving that flow to the material response.',
           'Uniform wire of length ℓ and area A, constant resistivity ρ, steady current; the material is ohmic over the operating range.',
           ['Current is I = dQ/dt, or average I = ΔQ/Δt. With carrier number density n_c, charge magnitude |q|, and drift-speed magnitude v_d, I = n_c|q|Av_d.',
            'The local material law is E = ρJ, with current density J = I/A. For uniform E, V = Eℓ = ρIℓ/A.',
            'Comparing V = IR gives R = ρℓ/A. This depends on the material law rather than being a universal law for every component.',
            'A small charge dQ transferring through voltage V transfers energy dE = V dQ. Divide by dt: P = VI. Substitute V = IR to obtain P = I²R = V²/R.',
            'When power is constant, total transferred energy is E_used = PΔt.'],
           'I = dQ/dt; R = ρℓ/A; P = IV = I²R = V²/R',
           'For the same material and length, a thicker wire has less resistance. Electrical resistivity ρ here has units Ω·m, unlike mass density.'),
    derive('Why sinusoidal rms values contain √2',
           'An rms value is the DC current or voltage that would produce the same average heating in a resistor.',
           'Sinusoidal steady state, purely resistive load R, average over a whole number of cycles.',
           ['Let i(t) = I_peak sin(ωt). Instantaneous resistor power is i²R = I_peak²R sin²(ωt).',
            'The cycle average of sin² is ½, so P_avg = I_peak²R/2.',
            'Set this equal to I_rms²R. Taking the positive root gives I_rms = I_peak/√2, and the same argument gives V_rms = V_peak/√2.'],
           'I_rms = I_peak/√2; V_rms = V_peak/√2; P_avg = V_rms I_rms (resistor)',
           'The average sinusoidal current is zero, but its rms value and heating are positive. A reactive AC circuit requires a power factor as well.'))

lesson(19, [27],
    derive('Kirchhoff rules, resistor networks, and real batteries',
           'Circuit junctions conserve charge, and a complete electrostatic loop accounts for energy per charge.',
           'Lumped DC circuit with negligible charge accumulation at junctions, ideal wires, and no unaccounted changing magnetic flux through a loop.',
           ['Charge balance at a junction gives ΣI_in = ΣI_out. Returning around a loop to the same potential gives ΣΔV_loop = 0.',
            'In series, current is shared and voltages add: V = ΣIRᵢ = IΣRᵢ. Therefore R_series = ΣRᵢ.',
            'In parallel, voltage is shared and currents add: I = ΣV/Rᵢ = VΣ(1/Rᵢ). Therefore 1/R_parallel = Σ1/Rᵢ.',
            'A discharging battery with emf ε and internal resistance r has loop equation ε − Ir − V_terminal = 0, giving V_terminal = ε − Ir.'],
           'ΣI_in = ΣI_out; ΣΔV_loop = 0; R_series = ΣRᵢ; 1/R_parallel = Σ1/Rᵢ; V_terminal = ε − Ir',
           'Parallel equivalent resistance is smaller than the smallest positive branch resistance. Battery terminal voltage equals its emf when current is zero.'),
    derive('RC charging and discharging',
           'As a capacitor charges, its growing voltage reduces the resistor’s voltage and current. The remaining voltage difference decays by a constant fraction per unit time.',
           'Ideal single resistor R and capacitor C; charging from Q(0) = 0 with constant emf ε, or discharging from initial charge Q₀ with the battery removed.',
           ['For charging, Kirchhoff’s loop rule gives ε − IR − Q/C = 0. Since I = dQ/dt, dQ/dt = (Cε − Q)/(RC).',
            'Define the charge deficit u = Cε − Q. Then du/dt = −u/(RC), so du/u = −dt/(RC).',
            'Integration gives u(t) = Cεe^(−t/RC), hence Q(t) = Cε[1 − e^(−t/RC)].',
            'For discharge, the remaining capacitor charge obeys dQ/dt = −Q/(RC); therefore Q(t) = Q₀e^(−t/RC). The discharge-current sign depends on the chosen loop direction.'],
           'τ = RC; Q_charge = Cε(1 − e^(−t/RC)); Q_discharge = Q₀e^(−t/RC)',
           'At one time constant, charging reaches about 63.2% of its final charge and discharging retains about 36.8%. At t = 0 the charging formula gives zero.'))

lesson(20, [28, 29],
    derive('Magnetic force, wire force, orbit radius, and loop torque',
           'The magnetic part of the Lorentz-force law is perpendicular to velocity. Summing it over moving charges produces the force on a current-carrying wire.',
           'Uniform B; nonrelativistic perpendicular motion for the circular-orbit formula; straight active wire length ℓ; planar coil with N turns.',
           ['Start with the physical law F = q(v × B), whose magnitude is |q|vB sin θ. Since F · v = 0, a magnetic field alone does no work on the charge.',
            'For v perpendicular to B, set |q|vB = mv²/r to obtain r = mv/(|q|B). Charge sign determines the direction of curvature.',
            'In a wire segment, the number of mobile carriers is n_cAℓ. Sum their magnetic forces and use I = n_c|q|Av_d to obtain F_wire = IℓB sin θ.',
            'The opposite forces on a rectangular loop make a couple. Force times perpendicular separation gives τ = IAB sin θ for one turn, or τ = NIAB sin θ.',
            'Define the magnetic moment magnitude μ = NIA, directed by the current right-hand rule. The vector torque is μ × B and orientation energy is U = −μ · B.'],
           'F = q(v × B); r = mv/(|q|B); F_wire = IℓB sin θ; τ_loop = NIAB sin θ',
           'A charge moving parallel to B feels no magnetic force. In the coil torque formula, θ refers to the area normal, not to the plane of the loop.'),
    derive('Fields from currents using Ampère’s law',
           'A symmetric current distribution lets us evaluate the magnetic circulation law without adding every current-element contribution separately.',
           'Steady currents in vacuum or air; an effectively infinite straight wire, or the central interior of a tightly wound long solenoid.',
           ['For steady currents, Ampère’s law states ∮B · dℓ = μ₀I_enclosed.',
            'Around a long straight wire, symmetry makes B tangent and constant on a circular path: B(2πr) = μ₀I.',
            'For a long solenoid, choose a rectangular path with one long side inside and one outside. The outside field is approximately zero and the crosswise sides contribute negligibly.',
            'If n is turns per unit length, a path of internal length ℓ encloses nℓ currents: Bℓ ≈ μ₀(nℓ)I.'],
           'B_wire = μ₀I/(2πr); B_solenoid ≈ μ₀nI',
           'These are symmetry-specific results. A short coil or a point near the solenoid ends requires a more complete field calculation.'))

lesson(21, [30, 31],
    derive('Flux, motional emf, and ideal transformers',
           'Faraday’s law connects induced emf to changing magnetic flux. Lenz’s sign makes the induced response oppose the change, consistent with energy conservation.',
           'Uniform field over each planar turn for Φ_B = BA cos θ; perpendicular rod motion for Bℓv; ideal transformer with common time-varying flux and negligible losses.',
           ['Define flux by Φ_B = ∫B · dA; for a uniform field and flat loop, Φ_B = BA cos θ. Faraday’s law states ε = −N dΦ_B/dt.',
            'For a rod of length ℓ sliding at speed v across parallel rails in perpendicular B, swept area changes at dA/dt = ℓv. Thus |ε| = Bℓv.',
            'Equivalently, magnetic force separates rod charges until |q|E = |q|vB, so the open-circuit voltage is Eℓ = Bℓv.',
            'Each ideal transformer turn links the same flux, so voltage magnitudes have ratio V_s/V_p = N_s/N_p. With no losses, input and output power match: V_pI_p = V_sI_s.'],
           'ε = −N dΦ_B/dt; |ε_motion| = Bℓv; V_s/V_p = N_s/N_p',
           'A steady flux gives zero induced emf. Increasing transformer voltage decreases available current by the inverse ratio under ideal power conservation.'),
    derive('Inductance and magnetic energy',
           'An inductor’s changing current changes its own linked flux, creating an emf that resists the current change.',
           'Linear constant inductance L; negligible winding resistance when calculating stored field energy.',
           ['Define flux linkage NΦ_B = LI. Faraday’s law gives ε_L = −d(LI)/dt = −L dI/dt for constant L.',
            'An external source raising the current must provide voltage V_L = L dI/dt. Its delivered power is P = IV_L = LI dI/dt.',
            'Thus dU = LI dI. Integrate from current 0 to I to obtain U_L = ½LI². Over a finite interval, average self-induced emf is −LΔI/Δt.'],
           'ε_L = −L dI/dt; U_L = ½LI²',
           'A constant current has zero ideal self-induced emf while retaining magnetic energy. If L depends strongly on current, the simple quadratic energy formula needs revision.'),
    derive('LC oscillations and series RLC resonance',
           'A capacitor stores electric energy and an inductor stores magnetic energy. Their exchange follows the same mathematics as a mass on a spring.',
           'Ideal lumped L and C; first take R = 0 and no source, then consider a series resistor and sinusoidal drive.',
           ['Let i = dQ/dt with a consistent passive circuit convention. The unforced loop equation is L d²Q/dt² + Q/C = 0.',
            'Compare with the oscillator equation x″ + ω₀²x = 0: ω₀ = 1/√(LC), so Q = Q_max cos(ω₀t + φ). Energy Q²/(2C) + ½Li² is constant.',
            'Adding resistance gives LQ″ + RQ′ + Q/C = ε(t). The term RQ′ dissipates energy and damps free oscillations.',
            'For sinusoidal steady state, differentiating current gives inductor reactance X_L = ωL, while integrating current gives capacitor reactance X_C = 1/(ωC). Their voltages are opposite in phase.',
            'The resistor voltage is in phase with current. The phasor right triangle gives Z = √[R² + (X_L − X_C)²] and I_rms = V_rms/Z. Reactances cancel at ω₀ = 1/√(LC).'],
           'ω₀ = 1/√(LC); Z = √[R² + (ωL − 1/(ωC))²]; P_avg = I_rms²R',
           'At series resonance Z = R and the driven current is largest for a fixed source voltage. Individual L and C voltages can still be large; they cancel in the loop sum.'))

lesson(22, [32, 33],
    derive('Maxwell’s equations and the speed of light',
           'Changing magnetic fields accompany circulating electric fields, and changing electric fields accompany circulating magnetic fields. Maxwell’s equations predict travelling waves.',
           'Vacuum, no free charges or conduction currents in the wave region; plane wave travelling along x, with E along y and B along z.',
           ['Gauss’s electric law is ∮E · dA = Q/ε₀, and its magnetic counterpart is ∮B · dA = 0. Faraday’s law is ∮E · dℓ = −dΦ_B/dt.',
            'Ampère–Maxwell law adds the changing-electric-flux term: ∮B · dℓ = μ₀I + μ₀ε₀ dΦ_E/dt. This term permits waves even where I = 0.',
            'For the stated plane-wave components, the curl equations reduce to ∂E_y/∂x = −∂B_z/∂t and ∂B_z/∂x = −μ₀ε₀∂E_y/∂t.',
            'Differentiate the first with respect to x and substitute the second to obtain ∂²E_y/∂x² = μ₀ε₀∂²E_y/∂t². Compare with the wave equation coefficient 1/c².',
            'For sinusoidal waves, kE₀ = ωB₀, so E₀/B₀ = ω/k = c. One wavelength passes per period, giving c = fλ.'],
           'c = 1/√(μ₀ε₀); E₀ = cB₀; c = fλ',
           'E, B, and propagation are mutually perpendicular for this plane wave. The result predicts light speed from electromagnetic constants.'),
    derive('Intensity and radiation pressure',
           'Electromagnetic waves transport both energy and momentum. Intensity is the average energy flux; pressure is momentum flux delivered to a surface.',
           'Sinusoidal vacuum plane wave; normal incidence on an ideal fully absorbing or reflecting surface.',
           ['The Poynting-vector magnitude is S = EB/μ₀. Substitute B = E/c to get S = cε₀E².',
            'For E = E₀ sin(kx − ωt), the cycle average of E² is E₀²/2, so I_avg = ½cε₀E₀².',
            'Radiation energy U carries forward momentum U/c. Absorbing energy I A dt delivers momentum I A dt/c, giving force IA/c and pressure I/c.',
            'Perfect reflection reverses the radiation momentum and doubles the momentum transfer, giving pressure 2I/c.'],
           'I_avg = ½cε₀E₀²; p_rad = I/c (absorption); p_rad = 2I/c (reflection)',
           'Pressure units are (W/m²)/(m/s) = N/m². Doubling electric-field amplitude quadruples intensity and radiation pressure.'))

lesson(23, [33, 34, 35],
    derive('Refraction and total internal reflection',
           'A wave must keep the same phase along an interface. Different wave speeds change its direction and wavelength while frequency stays fixed.',
           'Flat stationary interface between transparent media; n = c/v; angles measured from the surface normal.',
           ['Wave crests must match along the boundary, so their tangential wave-number components agree: k₁ sin θ₁ = k₂ sin θ₂.',
            'Since k = 2πf/v = 2πfn/c and f is unchanged at the interface, cancel the shared factor to get n₁ sin θ₁ = n₂ sin θ₂.',
            'The transmitted wavelength is λ_medium = v/f = λ_vacuum/n.',
            'For n₁ > n₂, the limiting transmitted angle is 90°. Setting sin θ₂ = 1 gives sin θ_c = n₂/n₁. Larger incidence angles have no propagating refracted ray in the second medium.'],
           'n₁ sin θ₁ = n₂ sin θ₂; λ_medium = λ_vacuum/n; sin θ_c = n₂/n₁',
           'Entering a higher-index medium bends a ray toward the normal. Total internal reflection requires travel from higher to lower index.'),
    derive('Thin-lens equation and magnification from similar triangles',
           'Two principal rays locate the image. Similar triangles connect image size to object distance and focal length.',
           'Thin converging lens, small paraxial angles, real object beyond its positive focal length for the geometric derivation; extend using signed distances for virtual images.',
           ['Let object height be h_o, real image height h_i < 0, and positive object and image distances d_o and d_i. The central ray gives h_i/h_o = −d_i/d_o.',
            'A ray entering parallel to the axis leaves through the far focal point. Its slope is −h_o/f, so at the image plane h_i = h_o(1 − d_i/f).',
            'Equate the two height ratios: −d_i/d_o = 1 − d_i/f. Divide by d_i and rearrange to 1/f = 1/d_o + 1/d_i.',
            'Thus magnification m = h_i/h_o = −d_i/d_o. For a spherical mirror, a near-axis normal tilts by approximately h/R; reflection doubles the tilt, making f ≈ R/2 and giving the analogous paraxial imaging equation.'],
           '1/f = 1/d_o + 1/d_i; m = −d_i/d_o; f_mirror ≈ R/2',
           'At d_o = 2f, the real image has d_i = 2f and m = −1. As d_o approaches f from above, the image distance grows without bound in the ideal model.'))

lesson(24, [33, 35, 36],
    derive('Double-slit fringes from path difference',
           'Phase differences arise when waves travel different distances. Whole-wavelength differences align crests; half-integer differences reverse them.',
           'Two coherent in-phase narrow slits, separation d, same wavelength λ in the propagation medium; far field, and small angles for screen-position formulas.',
           ['Far from the slits, the path difference is Δ = d sin θ. Phase difference is δ = 2πΔ/λ.',
            'Constructive interference occurs when δ = 2πm, hence d sin θ = mλ for integer m. Destructive interference occurs at Δ = (m + ½)λ.',
            'On a screen distance L away, tan θ = y/L. For small angles sin θ ≈ tan θ, giving y_m ≈ mλL/d.',
            'Subtract adjacent bright-fringe positions to obtain Δy ≈ λL/d. A multi-slit grating has the same principal-maximum condition, with sharper maxima.'],
           'd sin θ = mλ; y_m ≈ mλL/d; Δy ≈ λL/d',
           'Increasing wavelength widens fringes; increasing slit separation narrows them. At larger angles use the exact sine condition and y = L tan θ.'),
    derive('Single-slit minima and the diffraction envelope',
           'Every part of a finite-width slit contributes a wave. At certain angles those contributions cancel across the width.',
           'Uniformly illuminated slit of width a in the far field; scalar wave approximation.',
           ['At the first minimum, divide the slit into two equal halves. Pair points separated by a/2. Their path difference is (a/2)sin θ.',
            'When a sin θ = λ, each pair differs by λ/2 and cancels. For higher nonzero integer m, split the slit into 2|m| equal strips and pair adjacent strips to obtain a sin θ = mλ.',
            'Adding all phase contributions across the slit by integration gives amplitude proportional to sin u/u, with u = πa sin θ/λ.',
            'Intensity is proportional to squared amplitude, so I = I_central(sin u/u)². For two finite slits, multiply this envelope by the two-slit interference factor.'],
           'a sin θ = mλ, m = ±1, ±2, …; I/I_central = (sin u/u)²',
           'At θ = 0 the ratio approaches 1, so m = 0 is the central maximum, not a minimum. Slit width a and slit separation d play different roles.'),
    derive('Polarization and Malus’s law',
           'An ideal analyzer passes the electric-field component along its transmission axis. Intensity depends on the square of that component.',
           'Linearly polarized incident light and ideal linear analyzer; θ is the angle between polarization and transmission axes.',
           ['Project the incident field amplitude onto the analyzer axis: E_transmitted = E_incident cos θ.',
            'Since intensity is proportional to E², divide transmitted by incident intensity to get I/I₀ = cos²θ.',
            'For initially unpolarized light, averaging cos²θ over all directions gives ½, so a first ideal polarizer passes half the incident intensity.'],
           'I = I₀ cos²θ; I_after_first_polarizer = ½I_unpolarized',
           'Parallel axes transmit all of the already polarized input; crossed ideal axes transmit zero. I₀ in Malus’s law is the intensity arriving at the analyzer.'))

lesson(25, [34, 36],
    derive('Lens power, magnifiers, and telescopes',
           'Optical instruments change the angular size of an object at the eye. Their magnification follows from small-angle geometry.',
           'Thin lenses, paraxial rays, relaxed-eye viewing; near-point distance D_near is a chosen reference.',
           ['Lens power is defined by P_lens = 1/f with f in metres, giving dioptres. Aperture ratio is defined by f-number = f/D_aperture.',
            'An unaided object of height h at the near point subtends θ₀ ≈ h/D_near. A magnifier with the object at its focal plane sends parallel rays with angle θ ≈ h/f.',
            'Their angular ratio gives M_magnifier ≈ D_near/f.',
            'For a distant object at angular position θ, a telescope objective forms an intermediate image of height h ≈ f_objective θ. An eyepiece sends this image out at angle θ′ ≈ −h/f_eyepiece.',
            'Thus M_telescope = θ′/θ = −f_objective/f_eyepiece; the minus sign indicates inversion.'],
           'P_lens = 1/f; f-number = f/D; M_magnifier ≈ D_near/f; M_telescope = −f_o/f_e',
           'A longer objective focal length and shorter eyepiece focal length increase telescope angular magnification. Magnification by itself cannot overcome the diffraction resolution limit.'),
    derive('Diffraction resolution and Bragg’s law',
           'A finite aperture spreads a point source into a diffraction pattern. Crystal-plane reflections interfere according to their path difference.',
           'Circular aperture of diameter D; small angular separation; for Bragg reflection, parallel lattice planes separated by d with θ measured from the planes.',
           ['The circular-aperture diffraction solution has its first dark ring at sin θ ≈ 1.22λ/D. The coefficient 1.22 comes from adding waves over a circle, not from dimensional analysis.',
            'Rayleigh’s criterion takes the peak of one point image at the first minimum of the other, giving θ_min ≈ 1.22λ/D in radians.',
            'For rays reflected from adjacent crystal planes, the lower ray travels an extra d sin θ on entering and d sin θ on leaving.',
            'Constructive interference requires the total extra distance 2d sin θ to equal mλ.'],
           'θ_min ≈ 1.22λ/D; 2d sin θ = mλ',
           'Doubling aperture diameter halves the diffraction-limited angular separation. In Bragg’s law the angle is to the crystal planes, unlike a refraction angle measured from a normal.'))

lesson(26, [37],
    derive('Time dilation and length contraction',
           'The same light pulse has speed c in every inertial frame. Different path lengths therefore require different elapsed times.',
           'Inertial frames with relative speed v < c; proper time is measured where the two clock events occur at one location; lengths use simultaneous endpoint measurements in the measuring frame.',
           ['A light clock has mirror spacing d perpendicular to its motion. In its rest frame, half a round trip takes Δτ/2 = d/c.',
            'In a frame where the clock moves at v, a half-trip is diagonal: (cΔt/2)² = d² + (vΔt/2)².',
            'Insert d = cΔτ/2 and solve: Δt = Δτ/√(1 − v²/c²) = γΔτ.',
            'To measure a moving rod of rest length L₀, record endpoints simultaneously in the lab: Δt = 0. The Lorentz transformation gives Δx′ = γ(Δx − vΔt), so L₀ = γL.',
            'For a particle, the inverse transformations give dx = γ(dx′ + vdt′) and dt = γ(dt′ + vdx′/c²). Divide to obtain u = (u′ + v)/(1 + u′v/c²).'],
           'γ = 1/√(1 − v²/c²); Δt = γΔτ; L = L₀/γ; u = (u′ + v)/(1 + u′v/c²)',
           'As v/c approaches zero, γ approaches one and the velocity rule approaches u′ + v. If u′ = c, the transformed velocity is still c.'),
    derive('Relativistic energy and the classical limit',
           'Relativistic energy and momentum form a consistent pair. Their invariant relation separates rest energy from kinetic energy.',
           'Free particle of invariant rest mass m; p = γmv and E = γmc² are relativistic physical relations.',
           ['Substitute E and p into E² − p²c²: γ²m²c⁴ − γ²m²v²c² = γ²m²c⁴(1 − v²/c²) = m²c⁴.',
            'At rest γ = 1, so E_rest = mc². Subtract rest energy to obtain K = (γ − 1)mc².',
            'For v ≪ c, expand γ ≈ 1 + ½v²/c². Then K ≈ ½mv², recovering the classical equation.',
            'For a massless particle, the invariant relation reduces to E = pc. A photon therefore has momentum despite zero rest mass.'],
           'E² = p²c² + m²c⁴; K = (γ − 1)mc²; E_photon = pc',
           'The low-speed limit is a check of consistency. E = pc applies to a massless particle; it is not the general energy equation for a massive body.'))

lesson(27, [38, 40],
    derive('Photons, matter waves, and the photoelectric equation',
           'Photon energy and matter wavelength are quantum starting relations. Energy conservation then determines photoelectron energies.',
           'Single-photon photoelectric model for a clean surface with work function φ; V_stop is a positive stopping-voltage magnitude.',
           ['Use the quantum relation E = hf and the vacuum wave relation c = fλ to obtain E_photon = hc/λ.',
            'For a photon E = pc, so p = E/c = h/λ. Matter waves obey the de Broglie relation λ = h/p as a separate quantum principle.',
            'A photon supplies hf; at least φ is needed to remove the electron. The largest remaining electron kinetic energy is K_max = hf − φ.',
            'A stopping potential removes kinetic energy eV_stop, so eV_stop = K_max. At the emission threshold K_max = 0, giving f_threshold = φ/h.'],
           'E_photon = hf = hc/λ; λ_matter = h/p; K_max = hf − φ = eV_stop',
           'Below threshold this model predicts no emission even if intensity increases. Above threshold, greater intensity mainly increases electron count; greater frequency increases K_max.'),
    derive('Hydrogen-like energy levels in the Bohr model',
           'Coulomb attraction supplies circular acceleration, while Bohr’s historical angular-momentum postulate selects allowed orbits.',
           'One electron around charge +Ze; nonrelativistic Bohr model with a very heavy stationary nucleus. Modern quantum mechanics replaces the literal orbit picture.',
           ['Force balance gives m_ev²/r = k_eZe²/r². Bohr’s postulate is m_evr = nħ for n = 1, 2, … .',
            'Eliminate v to obtain r_n = n²ħ²/(m_ek_eZe²).',
            'Kinetic energy is ½m_ev² = k_eZe²/(2r), while potential energy is −k_eZe²/r. Thus E = −k_eZe²/(2r).',
            'Insert r_n to obtain E_n = −m_ek_e²Z²e⁴/(2n²ħ²) ≈ −13.6 Z²/n² eV.',
            'For a transition, energy conservation requires hf = |E_f − E_i|, with emission for a downward transition and absorption for an upward one.'],
           'E_n ≈ −13.6 Z²/n² eV; hf = |E_f − E_i|',
           'The negative energy means the electron is bound relative to the zero at infinite separation. The formula does not describe general many-electron atoms.'))

lesson(28, [38, 39, 40],
    derive('Confinement and the particle-in-a-box spectrum',
           'A confined matter wave must satisfy boundary conditions. Only certain wavelengths fit, so only certain momenta and energies are allowed.',
           'One nonrelativistic particle of mass m in a one-dimensional infinite square well from x = 0 to x = L.',
           ['The wavefunction vanishes at both walls. As for a fixed-end standing wave, L = nλ/2, so λ_n = 2L/n.',
            'Use p = h/λ to find momentum magnitude p_n = nh/(2L). Then E_n = p_n²/(2m) = n²h²/(8mL²).',
            'The stationary wavefunction is ψ_n = A sin(nπx/L). Normalization requires ∫₀ᴸ|ψ_n|²dx = 1. The integral of sin² over this interval is L/2, so A = √(2/L).',
            'If a photon drives a transition, its energy must equal the difference between the two allowed levels.'],
           'E_n = n²h²/(8mL²); ψ_n(x) = √(2/L) sin(nπx/L), n = 1, 2, …',
           'The lowest allowed energy is positive. Halving the well width quadruples every level energy; tighter confinement raises the kinetic-energy scale.'),
    derive('Uncertainty and counting atomic states',
           'A localized matter wave combines a spread of wave numbers. Atomic angular-momentum values and quantum numbers follow from quantum wave mechanics.',
           'σ denotes standard deviation. Atomic state counting uses the central-field quantum numbers and two electron spin states.',
           ['Fourier wave analysis gives σ_xσ_k ≥ ½. With pₓ = ħkₓ, multiply by ħ to obtain σ_xσ_pₓ ≥ ħ/2. This is a quantum wave result, not an effect of poor instruments.',
            'Angular wave solutions have L² eigenvalues ℓ(ℓ+1)ħ² and L_z eigenvalues m_ℓħ. Taking the positive square root gives |L| = √[ℓ(ℓ+1)]ħ.',
            'For fixed principal quantum number n, allowed ℓ values are 0 through n−1. For each ℓ, m_ℓ runs from −ℓ to +ℓ, giving 2ℓ+1 orbital states.',
            'Each orbital permits two spin states m_s = ±½. Sum 2Σ(2ℓ+1) from ℓ = 0 to n−1 to get a shell capacity of 2n² electrons under the Pauli principle.'],
           'σ_xσ_pₓ ≥ ħ/2; |L| = √[ℓ(ℓ+1)]ħ; L_z = m_ℓħ; shell capacity = 2n²',
           'The Bohr value nħ is not the modern orbital magnitude formula. An s orbital has ℓ = 0 and zero orbital angular momentum even though its electron has nonzero kinetic energy.'))

lesson(29, [40, 41],
    derive('Molecular vibration and rotation',
           'Near a stable bond length, a molecule behaves approximately like a spring. Rotation contributes a separate quantized energy.',
           'Diatomic molecule near equilibrium; harmonic vibration, rigid-rotor approximation, no strong vibration–rotation coupling.',
           ['For displacement x of the bond length, approximate U(x) = U_min + ½kx². The relative coordinate uses reduced mass μ = m₁m₂/(m₁+m₂).',
            'The classical vibration frequency is f = (1/2π)√(k/μ). Solving the quantum harmonic oscillator gives E_vib = (ν + ½)hf with ν = 0, 1, 2, … .',
            'A rigid rotor has classical energy L²/(2I). Substitute the quantum value L² = ℓ(ℓ+1)ħ² to obtain E_rot = ℓ(ℓ+1)ħ²/(2I).',
            'Allowed transitions require energy matching ΔE = hf_photon; additional selection rules determine which transitions actually occur.'],
           'E_vib = (ν + ½)hf; E_rot = ℓ(ℓ+1)ħ²/(2I)',
           'Harmonic vibrational levels have equal spacing hf, while rotor spacings grow with ℓ. The vibration ground state retains zero-point energy.'),
    derive('Band gaps, emitted light, and conduction',
           'In a solid, many atomic states form bands. An electron changing bands transfers an energy approximately set by the band gap.',
           'Simple band model; E_photon ≈ E_gap applies to ideal direct-gap radiative transitions near band edges. The one-carrier drift model is a simplified conduction model.',
           ['For an electron dropping from the conduction-band edge to a hole at the valence-band edge, energy conservation gives E_photon ≈ E_gap.',
            'Use E_photon = hc/λ to find λ ≈ hc/E_gap, or λ(nm) ≈ 1240/E_gap(eV).',
            'For one carrier species, current density magnitude is J = n_c|q|v_d. If v_d = μ_dE with mobility μ_d, then J = n_c|q|μ_dE.',
            'Compare with J = E/ρ to find resistivity ρ = 1/(n_c|q|μ_d). A semiconductor with both electrons and holes requires their conductivity contributions to be added.'],
           'E_photon ≈ E_gap; λ ≈ hc/E_gap; ρ = 1/(n_c|q|μ_d) (one carrier type)',
           'A larger direct band gap produces shorter-wavelength light. Carrier density and mobility both affect conductivity; a band-gap value alone does not determine a material’s resistance.'))

lesson(30, [42],
    derive('Exponential decay, activity, and half-life',
           'Each surviving nucleus has the same decay probability per unit time. The number decaying per unit time is therefore proportional to the number still present.',
           'One parent species, constant decay constant λ, no replenishment; N is a large-sample expectation.',
           ['Write dN/dt = −λN. Separate variables: dN/N = −λdt.',
            'Integrate from N₀ at 0 to N at t: ln(N/N₀) = −λt. Exponentiate to obtain N = N₀e^(−λt).',
            'At t = T½, N/N₀ = ½. Thus ln(½) = −λT½ and T½ = ln 2/λ.',
            'Insert λ = ln 2/T½ to rewrite N = N₀2^(−t/T½). Activity counts decays per second: A_activity = −dN/dt = λN.'],
           'N = N₀e^(−λt) = N₀2^(−t/T½); T½ = ln 2/λ; A_activity = λN',
           'After three half-lives, one eighth of the original parent population remains. Half-life is a population statistic, not a scheduled lifetime of an individual nucleus.'),
    derive('Nuclear size and binding energy',
           'Nuclei have approximately constant interior nucleon density. A bound nucleus also has less mass than its separated nucleons because energy was released on binding.',
           'Spherical nuclear-size estimate; use consistent nuclear masses, or neutral atomic masses with electron contributions properly accounted for.',
           ['If nuclear volume is proportional to nucleon count A, then (4/3)πR³ is proportional to A. Hence R = r₀A^(1/3), with empirical r₀ about 1.2 fm.',
            'For Z protons and N neutrons, the separated nuclear mass is Zm_p + Nm_n. Define mass defect Δm = Zm_p + Nm_n − M_nucleus.',
            'Mass–energy equivalence gives binding energy E_binding = Δmc². Dividing by A gives binding energy per nucleon.',
            'A mass difference of 1 u corresponds to about 931.5 MeV/c², so E_binding(MeV) ≈ Δm(u) × 931.5.'],
           'R ≈ r₀A^(1/3); E_binding = Δmc²; 1 u·c² ≈ 931.5 MeV',
           'Binding energy is positive for a stable bound nucleus. Mixing neutral atomic masses with bare proton masses introduces electron-mass errors.'))

lesson(31, [42, 43],
    derive('Reaction energy, fission, and fusion',
           'The change in total rest mass sets the energy available to products. Fission or fusion releases energy when it leads to more tightly bound products.',
           'Consistent initial and final mass conventions; include every reaction product and relevant excitation state.',
           ['Energy conservation reads Σm_initial c² + K_initial = Σm_final c² + K_final when all included energy terms are counted.',
            'Rearrange: Q_reaction = (Σm_initial − Σm_final)c² = K_final − K_initial. Positive Q means released rest energy.',
            'Expressing masses through nucleon masses minus binding energies shows Q = total final binding energy − total initial binding energy when nucleon counts are unchanged.',
            'The binding-energy-per-nucleon curve rises toward intermediate nuclei. Splitting suitable heavy nuclei or combining suitable light nuclei can therefore give positive Q. Charge, momentum, and other conservation laws still apply.'],
           'Q_reaction = (Σm_initial − Σm_final)c²',
           'A positive Q does not remove a reaction barrier. Fusion still requires overcoming or tunnelling through electrostatic repulsion.'),
    derive('Absorbed and equivalent radiation dose',
           'Absorbed dose counts deposited energy per mass. Equivalent dose applies a specified radiation weighting factor to that absorbed dose.',
           'Energy deposited in the stated tissue mass; w_R is the specified radiation-type weighting factor. These definitions are for physics bookkeeping.',
           ['Divide deposited energy E_deposited by irradiated mass m: D_abs = E_deposited/m, with 1 Gy = 1 J/kg.',
            'For one radiation type, define H_equiv = w_R D_abs in sieverts.',
            'For mixed radiation, add contributions: H_equiv = Σw_R D_R. Activity in becquerels counts decays per second and cannot be converted to dose without deposition and exposure information.'],
           'D_abs = E_deposited/m; H_equiv = Σw_R D_R',
           'The same deposited energy in twice the mass gives half the absorbed dose. Equivalent dose and effective dose are different quantities; the latter also uses tissue weighting.'))

lesson(32, [44],
    derive('Quark charges and particle-production thresholds',
           'Composite-particle charges add. Collision energy available in the centre-of-momentum frame sets a necessary threshold for making massive products.',
           'Valence-quark charge accounting; special-relativistic energy and momentum conservation for the complete initial state.',
           ['Use q_u = +⅔e and q_d = −⅓e. A proton uud has charge ⅔e + ⅔e − ⅓e = +e; a neutron udd has charge ⅔e − ⅓e − ⅓e = 0.',
            'Antiquarks have opposite charges. These fractions are physical inputs to the quark model, not consequences of the arithmetic.',
            'For total initial lab energy E_total and total momentum P_total, the invariant centre-of-momentum energy obeys E_CM² = E_total² − c²|P_total|².',
            'At the ideal threshold, final particles have no relative kinetic energy in that frame. Therefore E_CM must be at least Σm_final c²; additional conservation laws may forbid a proposed final state.'],
           'q_proton = +e; q_neutron = 0; E_CM = √(E_total² − c²|P_total|²) ≥ Σm_final c²',
           'Opposing equal-momentum collider beams have P_total = 0. A fixed-target beam generally spends some lab energy on overall product motion, so lab energy alone is not the available creation energy.'))

lesson(33, [13, 44],
    derive('Inverse-square brightness and parallax distance',
           'Luminosity spreads over a growing spherical area. Parallax instead finds distance from a geometric baseline and a small angular shift.',
           'Isotropic emission without absorption; source distance much larger than its size. Annual stellar parallax p uses a baseline radius of 1 astronomical unit.',
           ['A source with luminosity L sends that power through a sphere of area 4πd², so received flux is F = L/(4πd²).',
            'For a small parallax angle, p_radians ≈ 1 AU/d. By definition, 1 parsec is the distance where 1 AU subtends 1 arcsecond.',
            'Using the same angular units therefore gives d(parsecs) = 1/p(arcseconds).'],
           'F_received = L/(4πd²); d(pc) = 1/p(arcsec)',
           'Doubling distance quarters received flux and halves parallax. Apparent brightness alone cannot give distance unless luminosity is known or estimated.'),
    derive('Redshift, Hubble’s law, and an escape-speed analogy',
           'Redshift measures a wavelength ratio. Nearby expansion admits a linear speed–distance approximation; black-hole horizons require general relativity.',
           'Small redshift for v ≈ cz; nearby-universe Hubble approximation; a nonrotating uncharged black hole for r_s.',
           ['Define z = (λ_observed − λ_emitted)/λ_emitted. For small relative recession speeds, the Doppler expansion gives z ≈ v/c, hence v ≈ cz.',
            'The observed nearby expansion relation is v ≈ H₀d. Combining the approximations gives d ≈ cz/H₀. This estimates distance only within the approximation’s range.',
            'Newtonian escape energy sets ½mv_escape² − GMm/r = 0, giving v_escape = √(2GM/r).',
            'Formally setting this Newtonian expression equal to c gives r = 2GM/c². This reproduces the Schwarzschild radius algebraically, but the existence and meaning of an event horizon follow from general relativity.'],
           'z = Δλ/λ_emitted; v ≈ cz ≈ H₀d (nearby); r_s = 2GM/c²',
           'H₀ has dimensions inverse time. At large cosmological redshift, interpreting cz as a physical recession speed fails; the simple nearby distance conversion must be replaced.'))

assert set(DERIVATIONS) == set(range(1, 34))
assert {n for lesson in DERIVATIONS.values() for n in lesson['review_chapters']} == set(REVIEW_CHAPTERS)
